S=ROOT/'data/data_resources.csv'; P=ROOT/'data/data_products.csv'; D=ROOT/'data/product_distributions.csv'; B=ROOT/'data/brazil_scope_priorities.json'
def read(path):
    with path.open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def append(path,rows):
    with path.open(encoding='utf-8-sig',newline='') as f: fields=csv.DictReader(f).fieldnames
    with path.open('a',encoding='utf-8',newline='') as f:
        w=csv.DictWriter(f,fieldnames=fields,lineterminator=chr(10))
        for r in rows:
            if set(r)!=set(fields): raise SystemExit(f'schema mismatch {path}: {set(fields)-set(r)} / {set(r)-set(fields)}')
            w.writerow(r)
